// build-bundle.mjs (Mac-side ONLY, dev tool) — produces tenant/entrypoint.bundle.mjs: a
// single, dependency-free ESM file containing entrypoint.mjs plus every module it imports
// (./proof.mjs, ./public-job-state.mjs, the literal ../renew/survival-drive.mjs, ../market.mjs,
// and ../../spawn/lib/cloud-target.mjs, which market.mjs itself imports) with @solana/web3.js,
// bs58, and tweetnacl INLINED — so the container that runs this bundle needs nothing but `node`
// itself. This is the fix for the risk flagged in the first pass of this feature: this repo has
// never observed `npm install` succeeding from inside a Nosana job container (every other network
// call this project has proven live is to Solana RPC / Jupiter / the Nosana jobs API / GitHub —
// never npm), so the redesign removes that dependency entirely rather than trusting it.
//
// DELIBERATELY NOT under a directory named `dist/`: this repo's root .gitignore excludes any
// `dist/` directory anywhere in the tree (verified live — `git status` silently omitted a first
// attempt at `tenant/dist/entrypoint.bundle.mjs`, which `git check-ignore` then confirmed was
// matched by the blanket `dist/` rule). This artifact is NOT a disposable build byproduct like a
// typical `dist/` — it MUST be committed and pushed, since a live job fetches it by raw URL from a
// pinned commit. Living directly under `tenant/` avoids fighting that convention.
//
// Run this whenever entrypoint.mjs or anything it imports changes, THEN commit the regenerated
// tenant/entrypoint.bundle.mjs — bin/citizen-tenant-up's preflight check fetches the bundle from a
// pinned commit's raw URL, so a stale committed bundle would silently run old code.
//
// Usage: node skills/self/shelter/nosana/tenant/build-bundle.mjs

import path from "node:path";
import fs from "node:fs";
import { fileURLToPath } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));

/**
 * @param {{entryPoint?: string, outfile?: string, esbuildImpl?: object}} [opts]
 * @returns {Promise<{outfile: string, bytes: number}>}
 */
export async function buildEntrypointBundle({
  entryPoint = path.join(HERE, "entrypoint.mjs"),
  outfile = path.join(HERE, "entrypoint.bundle.mjs"),
  esbuildImpl,
} = {}) {
  const esbuild = esbuildImpl || (await import("esbuild"));
  fs.mkdirSync(path.dirname(outfile), { recursive: true });
  await esbuild.build({
    entryPoints: [entryPoint],
    bundle: true,
    platform: "node",
    format: "esm",
    target: "node20",
    outfile,
    legalComments: "none",
    banner: {
      // The trailing `createRequire` shim is esbuild's own documented workaround for ESM output:
      // some bundled CJS dependencies (e.g. inside @solana/web3.js's dependency tree) call
      // `require("<node-builtin>")` at runtime for interop; plain ESM has no global `require`.
      // Verified necessary live: without this, the bundle threw `Dynamic require of "buffer" is
      // not supported` the moment it ran.
      js:
        "// GENERATED by tenant/build-bundle.mjs — do not hand-edit. Edit entrypoint.mjs (or an imported module) and re-run `node skills/self/shelter/nosana/tenant/build-bundle.mjs`.\n" +
        "import { createRequire as __createRequire } from 'node:module';\n" +
        "const require = __createRequire(import.meta.url);\n",
    },
  });
  const bytes = fs.statSync(outfile).size;
  return { outfile, bytes };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const { outfile, bytes } = await buildEntrypointBundle();
  process.stdout.write(`build-bundle: wrote ${outfile} (${bytes} bytes)\n`);
}
